using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace PMSystem2.Api.Models;

[Table("improvements")]
public class Improvement
{
    [Key, Column("id")] public long Id { get; set; }
    // Generated by ImprovementsController when the client creates a record.
    [MaxLength(30), Column("code")] public string Code { get; set; } = string.Empty;
    [Required, MaxLength(200), Column("title")] public string Title { get; set; } = string.Empty;
    [MaxLength(100), Column("error_code")] public string? ErrorCode { get; set; }
    [Column("line_id")] public int? LineId { get; set; }
    [Column("station_id")] public int? StationId { get; set; }
    [Column("problem_description")] public string? ProblemDescription { get; set; }
    [Column("root_cause")] public string? RootCause { get; set; }
    [MaxLength(120), Column("owner")] public string? Owner { get; set; }
    [MaxLength(30), Column("status")] public string Status { get; set; } = "DRAFT";
    [Column("baseline_start")] public DateTime BaselineStart { get; set; }
    [Column("baseline_end")] public DateTime BaselineEnd { get; set; }
    [Column("tracking_start")] public DateTime TrackingStart { get; set; }
    [Column("tracking_end")] public DateTime TrackingEnd { get; set; }
    [Column("target_reduction_percent")] public double TargetReductionPercent { get; set; }
    [Column("created_at")] public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    [Column("updated_at")] public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
    public ICollection<ImprovementAction> Actions { get; set; } = new List<ImprovementAction>();
}

[Table("improvement_actions")]
public class ImprovementAction
{
    [Key, Column("id")] public long Id { get; set; }
    [Column("improvement_id")] public long ImprovementId { get; set; }
    [Required, MaxLength(300), Column("description")] public string Description { get; set; } = string.Empty;
    [MaxLength(120), Column("owner")] public string? Owner { get; set; }
    [MaxLength(30), Column("status")] public string Status { get; set; } = "TODO";
    [Column("due_date")] public DateTime? DueDate { get; set; }
    [Column("completed_at")] public DateTime? CompletedAt { get; set; }
    [Column("evidence")] public string? Evidence { get; set; }
    [Column("created_at")] public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    [ForeignKey(nameof(ImprovementId))]
    [System.Text.Json.Serialization.JsonIgnore]
    public Improvement? Improvement { get; set; }
}
